{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C29"],
      "claim": "Isradipine, a lipophilic dihydropyridine, had a mean systemic availability of 16.5% in healthy volunteers after oral administration, below the 20% threshold; this direct sub-20% F measurement supports a low-F prediction for the similarly lipophilic, poorly soluble query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine mean absolute oral bioavailability was 18% in healthy subjects, below the 20% threshold; this lipophilic drug with extensive first-pass metabolism supports a low-F prediction for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Nifedipine absolute bioavailability was 0.43 ± 0.14 after 30 mg oral tablets in subjects, above the 20% threshold; this is contradictory evidence, but nifedipine is much smaller and more soluble than the query, limiting its transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low: the query is a large, highly lipophilic polyisoprenoid quinone (CoQ10) with very poor aqueous solubility; direct sub-20% absolute F values in lipophilic comparators (isradipine 16.5%, pentazocine 18%) support low, while above-threshold values in smaller drugs (nifedipine 43%) are less transferable due to much lower molecular weight and better solubility.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the query molecule (CoQ10) in the provided evidence.",
    "All evidence molecules are structurally distinct small-molecule drugs; none capture the query's very high molecular weight and extreme lipophilicity.",
    "Absolute F for CoQ10 in humans is difficult to measure due to lack of IV formulation; extrapolation relies on physicochemical analogy."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

